  let primeraColor = '#1B1B1B';
  let cuadraColor = '#673DE6';

  const effectiveVariant = variant === 'auto' ? (isDark ? 'oscuro' : 'claro') : variant;

  if (effectiveVariant === 'blanco') {
    cornerStroke = '#FFFFFF';
    arrowColor = '#FFFFFF';
    primeraColor = '#FFFFFF';
    cuadraColor = '#FFFFFF';
  } else if (effectiveVariant === 'oscuro') {
    cornerStroke = '#F4F2EC';
    arrowColor = '#A48BFF';
    primeraColor = '#F4F2EC';
    cuadraColor = '#A48BFF';
  } else {
    // claro
    cornerStroke = '#1B1B1B';
    arrowColor = '#673DE6';
    primeraColor = '#1B1B1B';
    cuadraColor = '#673DE6';
  }

